// Generated albedos and numeric tangent-space maps. No material needs >4 texture units.
export function createL0Materials(T,renderer){
 const pending=[];const loader=new T.TextureLoader(),prefix='./assets/level0/',uniforms={time:{value:0}};
 const tex=(file,color=false)=>{let done,fail;pending.push(new Promise((resolve,reject)=>{done=resolve;fail=reject;}));const t=loader.load(prefix+file,done,undefined,fail);t.wrapS=t.wrapT=T.RepeatWrapping;t.colorSpace=color?T.SRGBColorSpace:T.NoColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return t;};
 const std=(name,color=0xffffff,scale=1,rough=.93)=>{const m=new T.MeshStandardMaterial({map:tex(name+'.jpg',true),normalMap:tex(name+'-normal.png'),normalScale:new T.Vector2(.7,.7),color,roughness:rough});worldUV(m,scale);return m;};
 const wall=[std('wallpaper-wheat',0xf1ecd1,1.6),std('wallpaper-sprigs',0xf2ecd4,1.4),std('wallpaper-lattice',0xf0ead0,1.5)];
 const carpet=std('carpet-berber-albedo',0xe2ddca,.60,.96),ceiling=std('ceiling-acoustic-albedo',0xe6e3d3,1.2,.96),insulation=std('insulation-fiberglass-albedo',0xf5e9cf,.45,1);
 ceiling.emissive.set(0x8d8877);ceiling.emissiveMap=ceiling.map;ceiling.emissiveIntensity=.65;carpet.normalScale.set(.40,.40);
 const plain=(color,roughness=.9)=>new T.MeshStandardMaterial({color,roughness});
 const mats={wall,carpet,ceiling,insulation,pink:plain(0xbe978b),wood:plain(0x695a37),metal:plain(0xa3a399,.56),dark:plain(0x141411),copper:plain(0x965830,.6),orange:plain(0xb96727,.7),pale:plain(0xe6e2c9),trim:plain(0x9a8d53),red:std('wallpaper-sprigs',0x813627,1.4,.94),redFloor:std('carpet-berber-albedo',0x9a4d3c,.72,.98),lamp:new T.MeshBasicMaterial({color:0xfffce6,toneMapped:false}),lampOff:plain(0x575749),void:new T.MeshBasicMaterial({color:0x090908}),pitWall:plain(0x4a4329),fabric:plain(0x7b7150)};
 mats.ao=new T.ShaderMaterial({transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1,uniforms:{},vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*instanceMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 vUv;void main(){float d=1.-max(abs(vUv.x-.5),abs(vUv.y-.5))*2.;float a=smoothstep(0.,.55,d)*.25;gl_FragColor=vec4(.10,.075,.025,a);#include <colorspace_fragment>\n}' .replace(';#include',';\n#include'),side:T.DoubleSide});
 uniforms.puddle={value:tex('carpet-puddle-albedo.jpg',true)};uniforms.brightness={value:1};
 mats.water=new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.DoubleSide,uniforms,vertexShader:`varying vec2 vUv;varying vec3 vWorld;void main(){vUv=uv;vec4 wp=modelMatrix*instanceMatrix*vec4(position,1.);vWorld=wp.xyz;gl_Position=projectionMatrix*viewMatrix*wp;}`,fragmentShader:`uniform float time;uniform float brightness;uniform sampler2D puddle;varying vec2 vUv;varying vec3 vWorld;
 float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.54);}float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1)),f.x),f.y);}
 void main(){vec2 p=(vUv-.5)*2.;float n=noise(p*3.+vWorld.xz*.07);float edge=1.-smoothstep(.66,.96,length(p)+(n-.5)*.27);if(edge<.015)discard;vec3 eye=normalize(cameraPosition-vWorld);float f=pow(1.-max(eye.y,0.),4.);float ripple=sin(length(p+vec2(.21,.12))*82.-time*2.)*.0019;vec2 rp=vWorld.xz+(eye.xz/max(eye.y,.1))*2.72;rp+=vec2(ripple);vec2 grid=abs(mod(rp+1.8,3.6)-1.8);float reflection=(1.-smoothstep(.43,.56,grid.x))*(1.-smoothstep(.12,.23,grid.y));vec3 c=mix(vec3(.075,.061,.032),vec3(.40,.38,.27),f);c+=vec3(.78,.76,.60)*reflection*(.17+.65*f);c=mix(texture2D(puddle,vUv).rgb*.44,c,.70)*brightness;gl_FragColor=vec4(c,edge*(.67+.25*f));\n#include <colorspace_fragment>\n}`});
 function worldUV(m,s){m.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 l0World; varying vec3 l0Normal;');shader.vertexShader=shader.vertexShader.replace('#include <worldpos_vertex>',`#include <worldpos_vertex>\nvec4 l0p=vec4(transformed,1.);\n#ifdef USE_INSTANCING\nl0p=instanceMatrix*l0p;\n#endif\nl0World=(modelMatrix*l0p).xyz;l0Normal=normalize(mat3(modelMatrix)*objectNormal);`);shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 l0World; varying vec3 l0Normal;');const uv=`(abs(l0Normal.y)>.5?l0World.xz:(abs(l0Normal.x)>.5?l0World.zy:l0World.xy))/${s.toFixed(4)}`;shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#ifdef USE_MAP\nvec4 sampledDiffuseColor=texture2D(map,${uv});diffuseColor*=sampledDiffuseColor;${s===.60?'diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.29,.26,.20),.52);':''}\n#endif`);shader.fragmentShader=shader.fragmentShader.replace('#include <normal_fragment_maps>',`#ifdef USE_NORMALMAP_TANGENTSPACE\nvec3 mapN=texture2D(normalMap,${uv}).xyz*2.-1.;mapN.xy*=normalScale;normal=normalize(tbn*mapN);\n#endif`);};m.customProgramCacheKey=()=>`level0WorldUV-${s}`;}
 mats.pink=insulation.clone();mats.pink.color.set(0xbca7a1);mats.pink.onBeforeCompile=insulation.onBeforeCompile;mats.pink.customProgramCacheKey=insulation.customProgramCacheKey;
 mats.pale.normalMap=wall[0].normalMap;mats.pale.normalScale=new T.Vector2(.18,.18);
 mats.pitWall=new T.ShaderMaterial({vertexShader:'varying float y;void main(){vec4 p=modelMatrix*instanceMatrix*vec4(position,1.);y=p.y;gl_Position=projectionMatrix*viewMatrix*p;}',fragmentShader:'varying float y;void main(){float a=exp(min(0.,y)*1.7);gl_FragColor=vec4(vec3(.29,.255,.16)*a,1.);\n#include <colorspace_fragment>\n}'});
 return {mats,uniforms,ready:Promise.all(pending)};
}
